import {mkpath, slurp, isFile, isDir} from 'fsys'
import {civet2js} from 'llcivet'

// ---------------------------------------------------------------------------

export const isHTML = (str: string): boolean => {

	return matches(str, /^(\s*\<!DOCTYPE.*?\>)?\s*\<html.*\<\/html\>\s*$/s)
}

// ---------------------------------------------------------------------------

export const isPug = (str: string): boolean => {

	return matches(str, /^(doctype\shtml\s)?html/s)
}

// ---------------------------------------------------------------------------

export const pug2html = (
		code: string,
		h: hash = {}
		): string => {

	return render(code, h)
}

// ---------------------------------------------------------------------------
// uses deno-webui
// see https://webui.me/docs.html#/deno

export class CHtmlWindow {

	window = new WebUI()
	html: string
	userScript: string
	converter: TStringMapper | TAsyncStringMapper
	hOptions: hash

	// ..........................................................

	constructor(
			source: string,
			userScript1 = '',
			hOptions1: hash = {}
			) {

		this.userScript = userScript1;

		this.hOptions = hOptions1;

		const html = (
			  source.endsWith('.html') ? slurp(source)
			: isHTML(source)           ? source
			: isPug(source)            ? pug2html(source)
			:                            'bad'
			)
		assert(isHTML(html), `Bad HTML source: ${abbrevStr(source)}`)
		this.html = html.replace(
			'</html>',
			`<script src="webui.js"></script>
<script src="https://cdnjs.cloudflare.com/ajax/libs/blissfuljs/1.0.6/bliss.min.js"></script>
<script>
	function elem(tag, h) {
		if (
				   (typeof h === 'string')
				|| (typeof h === 'number')
				|| (h instanceof Element)
				|| Array.isArray(h)
				) {
			return $.create(tag, {contents: h});
			}
		else {
			return $.create(tag, h);
			}
		}
</script>
</html>`)

		type opt = {
			isPublic: boolean
			width: number
			height: number
			converter: TStringMapper | TAsyncStringMapper
			}
		const {isPublic, width, height, converter,
			} = getOptions<opt>(this.hOptions, {
				isPublic: true,
				width: 800,
				height: 600,
				converter: civet2js
				})

		this.window.setPublic(isPublic)
		this.window.setSize(width, height)
		this.converter = converter
	}

	// ..........................................................
	// ASYNC

	async show(root: string): AutoPromise<void> {

		if (this.userScript) {
			const jsCode = await this.converter(this.userScript)
			this.html = this.html.replace(
				'</html>',
				`<script>${jsCode}</script></html>`)
		}
		this.window.setRootFolder(root)
		await this.window.showBrowser(this.html, WebUI.Browser.ChromiumBased)
		return
	}

	// ..........................................................
	// ASYNC

	async run(code: string): AutoPromise<void> {

		const jsCode = await this.converter(code)
		this.window.run(jsCode)
		return
	}

	// ..........................................................
	// ASYNC

	async script(code: string): AutoPromise<unknown> {

		const jsCode = await this.converter(code)
		return this.window.script(jsCode)
	}

	// ..........................................................

	close(): void {

		this.window.close()
	}

	// ..........................................................

	async [Symbol.dispose](): AutoPromise<void> {

		console.log("disposing HTML window")
		await WebUI.exit()
		console.log("cleaning up HTML window")
		await WebUI.clean()
	}
}

